// Unified UI composed around the existing datasets, grader, editor and tool views.
const stageNames={understand:'Understand',practice:'Practice',review:'Review',complete:'Complete'};
const projectNames=['Video Product Analytics','Social Product Analytics','AI Platform Economics','Warehouse and Reporting','CRM + ERP Integration'];
const mainNav=[['/','home','Home'],['/learn','book','Learn'],['/practice','code','Practice'],['/projects','projects','Projects'],['/progress','stats','Progress']];
const toolNav=[['/playground','db','SQL Playground'],['/lab','flask','Engineering Lab'],['/query-plans','plan','Query Plans'],['/dialects','globe','Dialect Guide'],['/warehouse','warehouse','Warehouse Blueprint']];
function action(label,name,attrs='',style='primary'){const accessible=attrs.match(/aria-label="([^"]+)"/);return `<button class="${style}" data-action="ux-${name}" ${attrs}${accessible?' title="'+accessible[1]+'"':''}>${label}</button>`;}
function link(label,path,style='textbutton'){return action(label,'route',`data-route="${path}"`,style);}
function rememberWorkspace(){if(['practice','playground','lab','assessment'].includes(state.page))persistDraft();}
function routeTo(path,push=true){rememberWorkspace();cancelWork();state.runSerial++;state.menuOpen=false;state.schemaOpen=false;state.commandOpen=false;state.resetConfirm=false;state.execution=null;state.result=null;state.feedback=null;state.expected=null;state.plan=null;if(push&&typeof history!=='undefined')history.pushState(null,'','#'+path);state.route=path;const parts=path.split('/').filter(Boolean);state.projectView=null;state.routeModule=null;
 if(parts[0]==='lesson'&&lessons[+parts[1]]){loadLesson(+parts[1],null,null);return;}
 if(parts[0]==='projects'&&caseStudyGroups[+parts[1]]&&parts.length>1){const pid=+parts[1];state.projectView=pid;learning.lastProject=pid;if(parts[2]==='milestone'&&caseStudyGroups[pid].ids.includes(+parts[3])){loadLesson(+parts[3],null,pid);return;}state.page='project';safePersist();render();return;}
 if(parts[0]==='learn'&&parts.length>1&&groups[+parts[1]]){state.page='module';state.routeModule=+parts[1];render();return;}
 const pages={'':'home',home:'home',learn:'path',practice:'launch',projects:'cases',progress:'progress',playground:'playground',lab:'lab','query-plans':'plans',dialects:'dialects',warehouse:'warehouse',settings:'settings',assessment:'assessment',review:'spaced'};state.page=pages[parts[0]||'']||'home';
 if(state.page==='launch'&&learning.active){const a=learning.active;loadLesson(a.id,a.variant,a.project);return;}
 if(state.page==='spaced'){const id=+parts[1];state.reviewId=lessons[id]?id:dueReviews()[0]?.id??0;state.reviewChoice=null;state.reviewResult=null;}
 if(state.page==='lab'){state.dataset='lab';try{const ds=sessionStorage.getItem('sql-lab-dataset');if(datasetCatalog[ds])state.dataset=ds;}catch(e){}state.query=learning.drafts['sql-lab-script']||lessons[59].example;}
 if(state.page==='playground'){state.query=learning.drafts['sql-playground-'+state.dataset]||'SELECT * FROM '+datasetCatalog[state.dataset].tables[0]+';';}
 if(state.page==='assessment'){if(!learning.placement||learning.placement.done)learning.placement={index:0,answers:[],done:false};state.placementIndex=learning.placement.index||0;state.placementAnswers=learning.placement.answers||[];loadPlacement();}
 render();}
function loadLesson(id,variant=null,project=null){state.page='practice';state.started=true;state.id=id;state.caseId=project;state.projectView=project;state.dataset=lessons[id].dataset;const previous=learning.active;state.variant=variant??learning.sessions['activity:'+project+':'+id]?.variant??(previous?.id===id&&previous.project===project?previous.variant:(project!==null?milestoneRecord(project,id).solved:record(id).solved).includes(0)?1:0);const session=learning.sessions[attemptKey()];state.stage=(STAGES.includes(session?.stage)?session.stage:null)||((project!==null?milestoneDone(project,id):mastered(id))?'complete':'understand');state.quizChoice=null;state.helpOpen=false;state.walkStep=0;state.walkResult=null;state.walkError=null;state.exampleResult=null;state.query=learning.drafts[draftKey()]??starter(id);state.assisted=attempt().guided;state.hint=attempt().hints;learning.active={id,variant:state.variant,stage:state.stage,project};if(project!==null){projectRecord(project).last=id;learning.lastProject=project;}safePersist();render();}
openLesson=function(id,variant){if(!lessons[id])return;rememberWorkspace();cancelWork();state.runSerial++;state.execution=null;state.result=null;state.expected=null;state.feedback=null;state.plan=null;const pid=state.caseId!==null&&caseStudyGroups[state.caseId]?.ids.includes(id)?state.caseId:null;const path=pid!==null&&caseStudyGroups[pid]?.ids.includes(id)?`/projects/${pid}/milestone/${id}`:`/lesson/${id}`;if(typeof history!=='undefined')history.pushState(null,'','#'+path);state.route=path;loadLesson(id,variant,pid);};
nav=function(page){routeTo(({home:'/',path:'/learn',cases:'/projects',progress:'/progress',lab:'/lab',plans:'/query-plans',dialects:'/dialects',warehouse:'/warehouse',playground:'/playground',practice:'/practice'})[page]||'/');};
function resume(){const a=learning.active;if(!a)return routeTo('/practice');routeTo(a.project!==null?`/projects/${a.project}/milestone/${a.id}`:`/lesson/${a.id}`);}
function followRecommendation(){const r=recommendedActivity();if(r.kind==='review')routeTo('/review/'+r.id);else if(r.project!==null)routeTo(`/projects/${r.project}/milestone/${r.id}`);else routeTo('/lesson/'+r.id);}
function setStage(stage){if(!STAGES.includes(stage))return;if(stage==='complete'&&!(state.caseId!==null?milestoneDone(state.caseId,state.id):mastered(state.id))){state.feedback={ok:false,title:'Keep building understanding',message:'Complete two independent challenges and the concept check first.'};return;}rememberWorkspace();state.stage=stage;persistDraft();render();}
function lessonStepper(){return `<nav class="stage-stepper" aria-label="Lesson stages">${STAGES.map((stage,i)=>`<button data-action="ux-stage" data-stage="${stage}" ${state.stage===stage?'aria-current="step"':''} ${stage==='complete'&&!(state.caseId!==null?milestoneDone(state.caseId,state.id):mastered(state.id))?'disabled':''}><span>${i+1}</span>${stageNames[stage]}</button>`).join('')}</nav>`;}
function lessonHeader(){const l=lessons[state.id],solves=ownSolves();return `<div class="lesson-heading"><div><div class="breadcrumb">${link('Learn','/learn')} / ${link(groups[l.group],'/learn/'+l.group)}${state.caseId!==null?' / '+link(projectNames[state.caseId],'/projects/'+state.caseId):''}</div><h1>${esc(l.title)}</h1><p class="note">${esc(l.grain)} · ${solves.length}/2 independent solves · ${(state.caseId!==null?milestoneRecord(state.caseId,state.id).check:record().check)?'Concept check passed':record().legacy?'Legacy mastery preserved':'Concept check pending'}</p></div>${action(icon('db')+' Schema','schema','','outline')}</div>${lessonStepper()}`;}
function understandView(){const l=lessons[state.id];return `<article class="lesson-reader"><div class="metadata">${datasetCatalog[l.dataset].name} · ${l.difficulty}</div><h2>The idea</h2><p class="concept">${esc(l.concept)}</p><section class="reader-example"><div class="section-heading"><h3>See it on actual data</h3><span class="metadata">SQLite</span></div><p>Run this example to inspect its output. Reading and running teaching examples preserve your independent status.</p><div class="embedded-code"><header><span>example.sql</span><div>${action(icon('copy'),'copy-example','aria-label="Copy teaching example"','iconbutton')}${action(icon('play')+' Run example','example-run','','outline')}</div></header><pre class="sqlblock">${syntax(l.example)}</pre>${state.exampleResult?`<div class="example-output">${table(state.exampleResult)}</div>`:''}</div></section><aside class="common-mistake"><h3>A mistake to watch for</h3><p>${esc(l.trap)}</p></aside>${l.dialectReference?`<details class="referenceonly"><summary>SQL Server reference · does not execute here</summary><pre class="sqlblock">${syntax(l.dialectReference)}</pre></details>`:''}<details class="walkthrough-disclosure"><summary>See it step by step</summary><p class="note">Answer-revealing walkthrough stages mark only this challenge attempt as guided.</p>${walkthrough()}</details><div class="lesson-primary">${action('Try it yourself '+icon('arrow'),'stage','data-stage="practice"')}</div></article>`;}
function challengeContext(){const l=lessons[state.id],t=l.tasks[state.variant],a=attempt();return `<section class="panel challenge-context"><div class="taskhead"><h2>Challenge ${state.variant+1} of 2</h2>${action(icon('up'),'task-toggle','aria-label="Collapse task pane"','iconbutton task-collapse')}</div><p class="challenge-reminder">${esc(t.prompt)}</p><details class="task-details"><summary>Tables & practice details</summary><p class="note">${esc(l.grain)}</p><p class="note">Relevant database: ${datasetCatalog[l.dataset].name}. Use Schema to inspect columns and preview rows.</p>${l.mode==='lab'?'<p class="labnotice">Fresh database for every execution. Include all setup statements and a final SELECT in this script.</p>':''}${a.fresh?'<p class="labnotice">Fresh-data retake. Table values have changed; preview the current data before solving.</p>':''}</details><div class="solve-progress">${[0,1].map(v=>`<span>${ownSolves().includes(v)?'✓':'○'} Challenge ${v+1}</span>`).join('')}</div><details class="hints" ${state.helpOpen?'open':''}><summary>Help with this challenge</summary><p class="note">Hints support learning. Use a fresh attempt to earn an independent solve.</p>${action(a.hints?'Next hint':'Hint 1 · direction','hint','','outline')}${a.hints?l.hints.slice(0,Math.min(a.hints,2)).map((h,i)=>`<p class="hinttext">${i+1}. ${esc(h)}</p>`).join(''):''}${a.hints>=3?'<p class="hinttext">Build the requested columns from the named tables, then check the output grain and edge cases. Reveal the authored solution only if you need it.</p>':''}${action('Reveal solution','reveal','','textbutton')}${a.revealed?`<pre class="sqlblock">${syntax(t.answer)}</pre>`:''}</details>${a.guided?'<p class="note">Guided attempt · your learning still counts. Independent credit needs a fresh-data attempt without challenge-specific help.</p>':''}${action(icon('db')+' Inspect schema','schema','','textbutton')}</section>`;}
function feedbackView(){const f=state.feedback;if(!f)return '';if(state.page!=='practice')return `<section class="feedback ${f.ok?'':'error'}" role="status"><strong>${esc(f.title)}</strong><p>${esc(f.message)}</p></section>`;const solves=ownSolves(),a=attempt();return `<section class="feedback ${f.ok?'':'error'}" role="status"><strong>${esc(f.title)}</strong><p>${esc(f.message)}</p>${state.execution?.evidence?`<p class="note">${esc(state.execution.evidence)}</p>`:''}${state.execution?.category?`<p class="note">Evidence category: ${esc(state.execution.category)}</p>`:''}${state.execution?.technical?`<details><summary>Database details</summary><pre class="sqlblock">${esc(state.execution.technical)}</pre></details>`:''}<div class="actions">${f.ok?solves.length===2?action('Review concept','stage','data-stage="review"'):a.guided?action('Try fresh data independently','fresh'):action('Next challenge','variant',`data-variant="${1-state.variant}"`):action('Keep editing','edit','','outline')}${action('Get a hint','hint','','textbutton')}${f.ok?'':action('Fresh attempt','fresh','','textbutton')}</div></section>`;}
function workspaceEditor(graded=true){const lab=state.page==='lab'||state.page==='practice'&&lessons[state.id].mode==='lab',r=state.outputTab==='plan'?state.plan:state.outputTab==='expected'?state.expected:state.result;return `<section class="editorzone" aria-label="SQL workspace" aria-busy="${state.busy}"><div class="editorpanel"><div class="editorhead"><span class="query-label">${icon('code')} query.sql</span><div class="editor-options"><span class="metadata">SQLite${lab?' · fresh database':''}</span>${action(icon('table'),'schema','aria-label="Inspect database schema"','iconbutton')}${action(icon('copy'),'copy','aria-label="Copy SQL"','iconbutton')}${action(icon('reset'),'reset','aria-label="Reset query"','iconbutton')}</div></div>${state.resetConfirm?`<div class="inline-confirm" role="status"><span>Replace this draft with the starter query?</span>${action('Reset draft','reset-confirm','','textbutton destructive')}${action('Keep draft','reset-cancel','','textbutton')}</div>`:''}<div class="editor" data-draft="${esc(draftKey())}"><div class="numbers" aria-hidden="true">${state.query.split('\n').map((_,i)=>i+1).join('\n')}</div><div class="codearea"><pre id="highlight" aria-hidden="true">${syntax(state.query)}</pre><textarea id="query" aria-label="SQL query editor" spellcheck="false" autocomplete="off" autocapitalize="off" autocorrect="off" wrap="off">${esc(state.query)}</textarea></div></div><div class="toolbar"><div class="execution-actions">${action(icon('play')+' Run query','run',state.busy?'disabled':'','outline')}${graded?action(icon('check')+' Check answer','check',state.busy?'disabled':''):''}</div><span class="keyboardhint">⌘/Ctrl + Enter <span>run</span></span></div><p class="editornote">${graded?'Run explores output. Check evaluates the active challenge and records an attempt.':'Run executes SQL without grading or mastery.'}</p></div>${feedbackView()}<details class="outputpanel" ${state.result||state.execution||state.plan?'open':''}><summary class="result-summary"><span>${icon('table')} Results</span><span class="metadata">${state.busy?'Executing…':state.result?(state.result.total??state.result.values.length)+' rows':'No query run yet'}</span></summary><div class="tabs outputtabs">${action('Output','output','data-tab="results"',state.outputTab==='results'?'active':'textbutton')}${graded&&state.page!=='assessment'?action(state.page==='practice'&&!ownSolves().includes(state.variant)?'Reference output · guided':'Reference output','expected',state.expected?'title="Revealing the reference before an independent solve makes this attempt guided"':'disabled title="Available after checking an answer"','textbutton'):''}${action('Query plan','plan',state.busy?'disabled':'','textbutton')}</div><div class="results">${state.outputTab==='expected'&&!state.expected?'<p class="note">Check an answer before revealing reference output. Revealing it before an independent solve makes this attempt guided.</p>':table(r)}${state.execution?`<p class="execution-status" role="status">${icon(state.execution.ok?'complete':'error')}${state.execution.ok?'Query executed':'Query needs attention'}${state.execution.total!==undefined?' · '+state.execution.total+' returned rows':''}</p>`:''}${state.outputTab==='plan'?'<p class="note">Actual SQLite EXPLAIN QUERY PLAN. SCAN/SEARCH are access paths, not measured production timing.</p>':''}</div></details></section>`;}
function practiceView(){return `<div class="practice-layout ${state.taskCollapsed?'task-collapsed':''}">${state.taskCollapsed?`<section class="task-peek"><span>Challenge ${state.variant+1}/2</span><p>${esc(lessons[state.id].tasks[state.variant].prompt)}</p>${action('Expand task '+icon('down'),'task-toggle','','textbutton')}</section>`:challengeContext()}${workspaceEditor(true)}</div>`;}
function reviewView(){const q=quizFor(state.id);return `<section class="panel teaching"><div class="meta">Review your understanding</div><h2>${esc(q.q)}</h2>${ownSolves().length<2?'<p class="labnotice">You can practice this check now. Mastery still needs two independent SQL solves.</p>':''}<div class="quizoptions">${q.options.map((o,i)=>action(`${String.fromCharCode(65+i)} · ${esc(o)}`,'quiz',`data-choice="${i}"`,'outline')).join('')}</div>${state.quizChoice!==null?`<div class="feedback ${state.quizChoice===q.correct?'':'error'}" role="status"><strong>${state.quizChoice===q.correct?'Correct understanding':'Let’s revisit the idea'}</strong><p>${esc(q.why)}</p>${state.quizChoice!==q.correct?action('Revisit explanation','stage','data-stage="understand"','outline'):action('Continue practicing','stage','data-stage="practice"','outline')}</div>`:''}</section>`;}
function completeView(){const m=moduleMetrics(lessons[state.id].group),next=nextInPath(state.id),project=caseStudyGroups.findIndex(c=>c.ids.includes(state.id));return `<section class="panel teaching completion"><div class="completion-mark">${icon('check')}</div><h2>${state.caseId!==null?'Milestone completed':'Lesson mastered'}</h2><p>${esc(lessons[state.id].concept)}</p><div class="completion-checks"><span>✓ Challenge 1 independently solved</span><span>✓ Challenge 2 independently solved</span><span>${(state.caseId!==null?milestoneRecord(state.caseId,state.id).legacy&&!milestoneRecord(state.caseId,state.id).check:record().legacy&&!record().check)?'✓ Legacy mastery preserved':'✓ Concept check passed'}</span></div><p class="note">${m.done} / ${m.ls.length} concepts mastered in ${groups[lessons[state.id].group]}.</p>${state.caseId!==null&&next===state.id?link('Return to project deliverables','/projects/'+state.caseId,'primary'):action('Continue to next lesson '+icon('arrow'),'next')}${project>=0?link('Apply this in a project','/projects/'+project):link('Explore projects','/projects')}</section>`;}
function unifiedLesson(){return `${state.caseId!==null?`<div class="project-strip">${link('← Project overview','/projects/'+state.caseId)}<span>${esc(projectNames[state.caseId])}</span><select id="ux-milestone" aria-label="Project milestone">${caseStudyGroups[state.caseId].ids.map((id,i)=>`<option value="${id}" ${state.id===id?'selected':''}>${i+1}. ${esc(lessons[id].title)}</option>`).join('')}</select></div>`:''}${lessonHeader()}${state.stage==='understand'?understandView():state.stage==='practice'?practiceView():state.stage==='review'?reviewView():completeView()}<div class="lessonfooter">${action('← Previous lesson','previous','','textbutton')}${action('Browse module','route',`data-route="/learn/${lessons[state.id].group}"`,'textbutton')}${action('Skip to next lesson →','skip','','textbutton')}</div>`;}
function summaryStats(){return {mastery:masteryCount(),independent:Object.values(state.stats).reduce((n,r)=>n+r.solved.length,0),checks:Object.values(state.stats).filter(r=>r.check).length,due:dueReviews().length};}
function homeView(){const a=learning.active,r=recommendedActivity(),s=summaryStats(),returning=!!a||state.history.length>0;return `<article class="editorial-home"><header class="editorial-intro"><div class="eyebrow">A WORKSPACE FOR LEARNING SQL</div><h1>${returning?'Pick up where you left off.':'Learn SQL by writing SQL.'}</h1><p>${returning?'Your learning and saved work are ready when you are.':'Understand the concepts, work with real datasets, and build practical projects as you learn.'}</p>${!returning?`<div class="actions">${action('Start learning '+icon('arrow'),'start')}${link('Check my level','/assessment','outline')}${link('Explore the course','/learn')}</div>`:''}</header>${returning&&a?`<section class="resume-section"><div class="section-label">${a.project!==null?esc(projectNames[a.project]):'Current lesson'} · ${groups[lessons[a.id].group]}</div><h2>${esc(lessons[a.id].title)}</h2><p class="metadata">${stageNames[a.stage]} · ${a.project!==null?milestoneRecord(a.project,a.id).solved.length:record(a.id).solved.length}/2 independent solves</p>${action('Continue '+icon('arrow'),'resume','',r.kind==='resume'?'primary':'outline')}</section>`:''}<div class="progress-summary">${s.mastery} of ${lessons.length} lessons mastered <span>·</span> ${s.due} reviews due ${link('View progress','/progress')}</div>${returning?`<section class="next-recommendation"><span class="section-label">Continue learning</span><div><h3>${r.kind==='review'?'Review: ':''}${esc(lessons[r.id].title)}</h3><p>${esc(r.reason)}</p></div>${r.kind==='resume'&&a?'':action('Open recommendation '+icon('arrow'),'recommend')}</section>`:`<section class="how-learning"><ol class="learning-overview">${[['Learn the fundamentals','Understand one concept, then run a real example.'],['Practice with SQL','Write, execute and check your queries.'],['Build real-world projects','Apply your understanding to business questions.']].map(([t,d],i)=>`<li><span class="index-number">0${i+1}</span><div><h3>${t}</h3><p>${d}</p></div></li>`).join('')}</ol><p class="metadata">${lessons.length} lessons · ${lessons.length*2} challenges · ${groups.length} modules · ${caseStudyGroups.length} projects</p></section>`}<section class="home-path"><div class="section-heading"><h2>Your learning path</h2>${link('Explore all lessons','/learn')}</div><div class="module-index compact-index">${moduleIndex()}</div></section>${!returning?`<section class="first-query"><div><span class="section-label">Start with a question</span><h2>Your first SQL query</h2><p>Select the columns you need from a table. You’ll run this against actual teaching data in your first lesson.</p>${link('Learn SELECT '+icon('arrow'),'/lesson/0')}</div><pre class="sqlblock">${syntax(lessons[0].example)}</pre></section><section class="featured-project"><span class="section-label">Build toward real analysis</span><h3>${projectNames[0]}</h3><p>${esc(caseStudyGroups[0].description)}</p>${link('Explore this project '+icon('arrow'),'/projects/0')}</section>`:learning.lastProject!==null?`<section class="featured-project"><span class="section-label">Your project workspace</span><h3>${projectNames[learning.lastProject]}</h3>${link('Resume project '+icon('arrow'),'/projects/'+learning.lastProject)}</section>`:''}${state.history.length?`<section class="recent-work"><h2>Recent work</h2>${activityRows(state.history.slice(-3))}</section>`:''}</article>`;}
function moduleIndex(){return groups.map((g,i)=>{const m=moduleMetrics(i);return `<section class="module-row"><span class="index-number">${String(i+1).padStart(2,'0')}</span><div class="index-content"><h2>${link(esc(g),'/learn/'+i,'row-title')}</h2><p>${esc(moduleDescriptions[i])}</p><span class="metadata">${m.ls.length} lessons · ${m.ls[0].difficulty} · ${m.status}</span></div><div class="index-progress"><span>${m.done}/${m.ls.length} mastered</span><div class="bar"><i style="width:${100*m.done/m.ls.length}%"></i></div></div>${link(icon('right'),'/learn/'+i,'iconbutton index-open').replace('data-route=',`aria-label="Open ${esc(g)}" title="Open module" data-route=`)}</section>`;}).join('');}
function filtersView(){return `<details class="search-filters" ${state.search?'open':''}><summary>Find a lesson or skill</summary><div class="filters-grid"><label>Search<input id="ux-search" type="search" value="${esc(state.search)}" placeholder="e.g. JOIN, NULL, retention"></label><label>Difficulty<select id="ux-level">${['all','Beginner','Intermediate','Advanced'].map(x=>`<option value="${x}" ${state.filterLevel===x?'selected':''}>${x==='all'?'All levels':x}</option>`).join('')}</select></label><label>Module<select id="ux-module"><option value="-1">All modules</option>${groups.map((g,i)=>`<option value="${i}" ${state.pathGroup===i?'selected':''}>${g}</option>`).join('')}</select></label><label>Status<select id="ux-status">${['all','Not started','In progress','Guided practice','Mastered','Review recommended'].map(x=>`<option value="${x}" ${state.filterStatus===x?'selected':''}>${x==='all'?'All statuses':x}</option>`).join('')}</select></label></div>${action('Search course','search','','outline')}</details>`;}
function searchMatches(){return courseOrder.map(id=>lessons[id]).filter(l=>(state.pathGroup<0||l.group===state.pathGroup)&&(state.filterLevel==='all'||state.filterLevel===l.difficulty)&&(state.filterStatus==='all'||state.filterStatus===lessonStatus(l.id))&&`${l.title} ${l.concept} ${groups[l.group]}`.toLowerCase().includes(state.search.toLowerCase()));}
function lessonRows(ls){return ls.map(l=>`<div class="pathrow"><span class="num">${String(courseOrder.indexOf(l.id)+1).padStart(2,'0')}</span><div class="title">${esc(l.title)}<small>${l.difficulty} · 2 SQL challenges + concept check</small></div><span class="state ${mastered(l.id)?'done':''}">${lessonStatus(l.id)}</span>${link('Open →','/lesson/'+l.id)}</div>`).join('');}
function learnView(){const filtered=state.search||state.filterLevel!=='all'||state.filterStatus!=='all'||state.pathGroup>=0;return `<header class="page-intro"><div><h1>Your SQL learning path</h1><p>${masteryCount()}/${lessons.length} lessons mastered. Explore any lesson; prerequisites are recommendations.</p></div>${learning.active?action('Continue learning '+icon('arrow'),'recommend','','outline'):link('Start with basics','/lesson/0','primary')}</header>${filtersView()}${filtered?`<section class="search-results">${lessonRows(searchMatches())||'<div class="empty">No matching lessons. Change your search or filters.</div>'}${action('Clear filters','clear-filters','','textbutton')}</section>`:`<div class="module-index">${moduleIndex()}</div>`}`;}
function moduleView(){const i=state.routeModule,m=moduleMetrics(i),prereqs=[...new Set(m.ls.flatMap(l=>l.prereq||[]))].filter(id=>lessons[id].group!==i).slice(0,5),p=caseStudyGroups.findIndex(c=>c.ids.some(id=>lessons[id].group===i));return `<article class="module-intro"><div class="breadcrumb">${link('Learning path','/learn')} / Module ${String(i+1).padStart(2,'0')}</div><h1>${esc(groups[i])}</h1><p class="lead">${esc(moduleDescriptions[i])}</p><p class="metadata">${m.ls.length} lessons · ${m.done} mastered · ${m.status}</p><div class="module-context"><section><h2>What you’ll learn</h2><p>${esc(m.ls.map(l=>l.title).join(' · '))}</p><h3>Why it matters</h3><p>Write queries with a clear output grain, inspect actual rows, and verify your logic on changed data.</p></section><section><h3>Useful prerequisites</h3>${prereqs.length?prereqs.map(id=>link(lessons[id].title,'/lesson/'+id)).join(''):'<p class="note">Start here with no SQL experience.</p>'}${p>=0?`<h3>Apply these skills</h3>${link(projectNames[p],'/projects/'+p)}`:''}</section></div></article><div class="lesson-index">${lessonRows(m.ls)}</div>`;}
function projectCatalog(){return `<header class="page-intro"><div><h1>Put SQL to work.</h1><p>Realistic business questions. Your own queries, milestones and saved deliverables.</p></div></header><div class="project-index">${caseStudyGroups.map((c,p)=>{const count=c.ids.filter(id=>milestoneDone(p,id)).length,r=learning.projects[p];return `<section class="project-row"><span class="index-number">0${p+1}</span><div class="index-content"><h2>${link(projectNames[p],'/projects/'+p,'row-title')}</h2><p>${esc(c.description)}</p><span class="metadata">${datasetCatalog[c.dataset].name} · ${p<3?'Intermediate / Advanced':'Advanced'}</span><p class="skills-line">${c.ids.map(id=>esc(lessons[id].title)).slice(0,3).join(' · ')}</p></div><div class="project-status"><span class="metadata">${count}/${c.ids.length} milestones</span>${link(r?'Resume '+icon('arrow'):'Start '+icon('arrow'),'/projects/'+p,'outline')}</div></section>`;}).join('')}</div>`;}
function projectView(){const p=state.projectView,c=caseStudyGroups[p],r=learning.projects[p],count=c.ids.filter(id=>milestoneDone(p,id)).length,next=r?.last&&c.ids.includes(r.last)?r.last:c.ids.find(id=>!milestoneDone(p,id))??c.ids[0];return `<header class="project-intro"><div class="breadcrumb">${link('Projects','/projects')} / ${datasetCatalog[c.dataset].name}</div><h1>${projectNames[p]}</h1><p class="lead">${esc(c.description)}</p><div class="actions">${link(r?'Resume milestone '+icon('arrow'):'Start project '+icon('arrow'),`/projects/${p}/milestone/${next}`,'primary')}<span class="metadata">${count}/${c.ids.length} milestones completed</span></div></header><section class="project-brief"><h2>The business brief</h2><p>Act as ${datasetCatalog[c.dataset].role.toLowerCase()}. ${esc(datasetCatalog[c.dataset].description)}</p><h3>Your deliverables</h3><p>Two independent checked SQL queries and a concept check per milestone. Your SQL and bounded checked results are saved; visiting a milestone does not complete it.</p>${r?.migrated?'<p class="note">Prior milestone mastery has been preserved. Earlier versions did not save project result snapshots; open a milestone to create new deliverables.</p>':''}<details class="runtime-details"><summary>How the project database works</summary><p>Every execution starts with fresh teaching data. Include the full setup script for write tasks. SQL and checked results persist; created tables do not carry between executions.</p></details><div class="actions">${action(icon('copy')+' Export SQL','export-project',`data-project="${p}"`,'textbutton')}${action('Export summary','export-summary',`data-project="${p}"`,'textbutton')}${p>=3?link('Warehouse blueprint '+icon('arrow'),'/warehouse'):''}</div></section><section class="milestone-index"><h2>Your milestones</h2>${c.ids.map((id,i)=>{const m=r?.milestones?.[id];return `<section class="milestone-row"><span class="index-number">${String(i+1).padStart(2,'0')}</span><div class="index-content"><h3>${esc(lessons[id].title)}</h3><p>${esc(lessons[id].tasks[0].prompt)}</p><span class="metadata">${milestoneDone(p,id)?'✓ Complete':m?'In progress':'Not started'} · ${m?.solved?.length||0}/2 independent solves · ${m?.check?'Concept check passed':m?.legacy?'Legacy mastery preserved':'Concept check pending'}</span>${m?.queries&&Object.keys(m.queries).length?`<details class="deliverable-view"><summary>Saved deliverables</summary>${Object.entries(m.queries).map(([v,q])=>`<h4>Challenge ${+v+1}</h4><pre class="sqlblock">${syntax(q)}</pre><p class="metadata">${m.results?.[v]?.ok?'Checked successfully':'Last check needs revision'} · ${m.results?.[v]?.guided?'Guided':'Independent'}</p>${m.results?.[v]?.columns?.length?table(m.results[v]):''}`).join('')}</details>`:''}</div>${link(m?'Resume '+icon('arrow'):'Open '+icon('arrow'),`/projects/${p}/milestone/${id}`,'textbutton')}</section>`;}).join('')}</section>${projectDone(p)?'<section class="completion-summary"><h2>Project complete</h2><p>Every milestone has recorded mastery, including preserved legacy credit where applicable.</p></section>':''}`;}
function progressView(){const s=summaryStats(),r=recommendedActivity(),weak=lessons.filter(l=>record(l.id).errors>=2),reviews=lessons.filter(l=>mastered(l.id)&&learning.reviews[l.id]).sort((a,b)=>learning.reviews[a.id].due-learning.reviews[b.id].due);return `<header class="page-intro"><div><h1>Your SQL skills.</h1><p class="progress-summary">${s.mastery} lessons mastered · ${s.independent} independent solves · ${s.due} reviews due</p></div></header><section class="next-recommendation"><span class="section-label">Recommended next</span><div><h3>${esc(lessons[r.id].title)}</h3><p>${esc(r.reason)}</p></div>${action('Continue '+icon('arrow'),'recommend')}</section><section class="skills-section"><h2>Your skills</h2>${groups.map((g,i)=>{const m=moduleMetrics(i);return `<div class="skill-row"><span class="index-number">${String(i+1).padStart(2,'0')}</span><div>${link(esc(g),'/learn/'+i,'row-title')}<span class="metadata">${m.status}</span></div><div class="bar"><i style="width:${100*m.done/m.ls.length}%"></i></div><span class="metadata">${m.done}/${m.ls.length}</span></div>`;}).join('')}</section><section class="practice-needs"><h2>Needs practice</h2>${weak.length?weak.slice(0,5).map(l=>`<div class="review-row"><div><h3>${esc(l.title)}</h3><p class="metadata">${Object.entries(record(l.id).categories||{}).map(([k,v])=>`${esc(k)}: ${v} checks`).join(' · ')||'Repeated unsuccessful attempts'}</p></div>${link('Practice '+icon('arrow'),'/lesson/'+l.id,'textbutton')}</div>`).join(''):'<p class="note">No repeated difficulties recorded. Your checked attempts will help identify skills to revisit.</p>'}</section><section class="review-queue"><div class="section-heading"><h2>Review schedule</h2><span class="metadata">1 → 3 → 7 → 21 days</span></div><p class="note">Correct reviews advance the interval; incorrect reviews return to tomorrow. Reviews preserve original mastery.</p>${reviews.length?reviews.slice(0,8).map(l=>`<div class="review-row"><div><h3>${esc(l.title)}</h3><span class="metadata">${learning.reviews[l.id].due<=Date.now()?'Review due':new Date(learning.reviews[l.id].due).toLocaleDateString()}</span></div>${link('Review '+icon('arrow'),'/review/'+l.id,'textbutton')}</div>`).join(''):'<p class="note">No reviews scheduled yet. Master a lesson to start the review cycle.</p>'}</section><section class="progress-projects"><h2>Projects</h2>${caseStudyGroups.map((c,p)=>{const record=learning.projects[p],n=c.ids.filter(id=>milestoneDone(p,id)).length;return `<div class="review-row"><div><h3>${projectNames[p]}</h3><span class="metadata">${projectDone(p)?'Complete':record?'In progress':'Not started'} · ${n}/${c.ids.length} milestones</span></div>${link(record?'Resume '+icon('arrow'):'Explore '+icon('arrow'),'/projects/'+p,'textbutton')}</div>`;}).join('')}</section><section class="recent-work"><h2>Learning history</h2>${state.history.length?activityRows(state.history.slice(-8)):'<p class="note">Your checked challenges will appear here.</p>'}</section><footer class="data-controls"><p class="note">${storageOK?'Saved in this browser. Export to move your progress and SQL to another device.':'Browser storage is unavailable. Export before leaving to preserve your work.'} No account or cloud sync.</p><div class="actions">${action('Export progress','export','','outline')}<label class="importbutton">Import progress<input type="file" id="ux-import" accept="application/json" hidden></label>${link('Settings','/settings')}${action('Reset learning data','clear','','textbutton destructive')}</div></footer>`;}
const placementIds=[0,3,5,10,14,32];
function loadPlacement(){const id=placementIds[state.placementIndex]??0;state.dataset=lessons[id].dataset;state.query=learning.drafts[draftKey()]||'-- Write SQL for this diagnostic question\n';}
function placementView(){const p=learning.placement;if(p?.done){const prefix=p.answers.findIndex(x=>!x.ok),n=prefix<0?p.answers.length:prefix,id=[0,3,5,10,14,21,32][n];return `<section class="panel teaching"><h1>Your starting recommendation</h1><p>You solved ${p.answers.filter(x=>x.ok).length}/${placementIds.length} diagnostic questions. The starting point follows your consecutive foundational successes; a single advanced answer cannot skip the foundations.</p><h2>${lessons[id].title}</h2><p class="note">This suggests an entry point. It has not marked any course concept mastered.</p>${link('Start recommended lesson','/lesson/'+id,'primary')}${link('Browse the course','/learn')}</section>`;}const l=lessons[placementIds[state.placementIndex]];return `<section class="panel teaching"><div class="meta">Optional diagnostic · ${state.placementIndex+1}/${placementIds.length}</div><h1>${l.title}</h1><p>${l.tasks[0].prompt}</p><p class="note">Use Schema to inspect the actual dataset. Diagnostic checks do not award lesson mastery.</p>${action('Schema','schema','','outline')}</section>${workspaceEditor(true)}${state.execution?`<div class="actions">${action(state.placementIndex===placementIds.length-1?'See recommendation':'Next question','placement-next')}${link('Leave assessment','/')}</div>`:''}`;}
function spacedView(){const id=state.reviewId,q=quizFor(id);return `<section class="panel teaching"><div class="meta">Spaced review · ${lessons[id].title}</div><h1>${q.q}</h1><div class="quizoptions">${q.options.map((o,i)=>action(esc(o),'review-answer',`data-choice="${i}"`,'outline')).join('')}</div>${state.reviewResult?`<div class="feedback ${state.reviewResult.ok?'':'error'}" role="status"><p>${q.why}</p><p class="note">Next review: ${new Date(learning.reviews[id].due).toLocaleDateString()}. Original mastery is preserved.</p>${link('Revisit the explanation','/lesson/'+id,'outline')}${action('Continue learning','recommend')}</div>`:''}</section>`;}
function themeControls(){const t=learning.preferences.theme;return `<label class="theme-control">${icon(t==='system'?'monitor':t==='dark'?'moon':'sun')}<span class="sr-only">Appearance</span><select class="ux-theme" aria-label="Appearance">${['system','light','dark'].map(x=>`<option value="${x}" ${t===x?'selected':''}>${x==='system'?'System':x==='dark'?'Dark':'Light'}</option>`).join('')}</select></label>`;}
function applyTheme(){const pref=learning.preferences.theme,dark=pref==='dark'||pref==='system'&&typeof matchMedia==='function'&&matchMedia('(prefers-color-scheme: dark)').matches;document.documentElement?.setAttribute?.('data-theme',dark?'dark':'light');if(typeof getComputedStyle==='function')document.querySelector?.('meta[name="theme-color"]')?.setAttribute?.('content',getComputedStyle(document.documentElement).getPropertyValue('--bg').trim());try{localStorage.setItem('sql-studio-theme',pref)}catch(e){} }
function shellNav(items){return items.map(([path,i,label])=>{const active=path==='/practice'?state.page==='practice':path==='/learn'?['path','module'].includes(state.page):path==='/projects'?['cases','project'].includes(state.page):path==='/'?state.page==='home':state.route===path;return `<button data-action="ux-route" data-route="${path}" aria-label="${label}" title="${label}" ${active?'aria-current="page"':''} class="${active?'active':''}">${icon(i)}<span class="navtext">${label}</span></button>`;}).join('');}
render=function(){applyTheme();const titles={home:'Home',path:'Learn',module:'Module',practice:state.caseId!==null?'Project workspace':'Lesson',launch:'Practice',cases:'Projects',project:'Project workspace',progress:'Progress',playground:'Playground',lab:'Engineering Lab',plans:'Query Plans',dialects:'Dialect Guide',warehouse:'Warehouse Blueprint',assessment:'Check your level',spaced:'Spaced review',settings:'Settings'};const content=state.page==='home'?homeView():state.page==='path'?learnView():state.page==='module'?moduleView():state.page==='practice'?unifiedLesson():state.page==='launch'?`<article class="editorial-intro"><h1>Your first query starts here.</h1><p>Learn SELECT, practice on actual data, then check your understanding.</p><div class="actions">${link('Start learning','/lesson/0','primary')}${link('Explore the course','/learn')}</div></article>`:state.page==='cases'?projectCatalog():state.page==='project'?projectView():state.page==='progress'?progressView():state.page==='assessment'?placementView():state.page==='spaced'?spacedView():state.page==='settings'?settingsView():state.page==='playground'?playground():state.page==='lab'?engineeringLab():state.page==='plans'?planLab():state.page==='warehouse'?warehouseProject():dialects();root.innerHTML=`<a class="skiplink" href="#main-content">Skip to content</a><header class="mobilebar"><div class="brand">${icon('db')}<span>SQL Studio</span></div><div>${action(icon('search'),'command','aria-label="Search SQL Studio"','iconbutton')}${action(icon('menu'),'menu','aria-label="Open navigation" aria-expanded="'+state.menuOpen+'" aria-controls="site-sidebar"','iconbutton menutoggle')}</div></header>${state.menuOpen?action('','closemenu','aria-label="Close navigation"','drawer-backdrop'):''}<aside id="site-sidebar" class="sidebar ${state.menuOpen?'is-open':''} ${learning.preferences.collapsed?'compact':''}" ${state.menuOpen?'role="dialog" aria-modal="true"':''} aria-label="Main navigation"><div class="brand">${icon('db')}<span class="brandtext">SQL Studio</span>${action(icon('menu'),'collapse','aria-label="'+(learning.preferences.collapsed?'Expand':'Collapse')+' sidebar"','iconbutton collapse-control')}${action(icon('close'),'closemenu','aria-label="Close navigation"','iconbutton menuclose')}</div><nav class="nav" aria-label="Learning navigation">${shellNav(mainNav)}</nav><details class="tools-group" ${['playground','lab','plans','dialects','warehouse'].includes(state.page)?'open':''}><summary title="SQL tools">${icon('more')}<span class="navtext">Tools</span>${icon('down')}</summary><nav class="nav" aria-label="Optional SQL tools">${shellNav(toolNav)}</nav></details><footer class="sidefoot">${link(icon('settings')+'<span class="navtext">Settings</span>','/settings','settings-link').replace('data-route=','aria-label="Settings" title="Settings" data-route=')}${themeControls()}<span class="local-status">${storageOK?'Progress saved locally':'Storage unavailable'}</span></footer></aside><main id="main-content" class="main ${learning.preferences.collapsed?'with-compact':''}" data-page="${state.page}" tabindex="-1"><header class="topbar"><span class="workspace-label">${titles[state.page]}</span>${action(icon('search')+'<span>Search SQL Studio</span><kbd>⌘ K</kbd>','command','aria-label="Search and quick navigation"','command-trigger')}${themeControls()}</header><div class="page-content">${content}</div></main><nav class="bottomnav" aria-label="Mobile navigation">${shellNav(mainNav)}</nav>${state.schemaOpen?`<div class="schema-overlay">${action('','schema','aria-label="Close schema"','drawer-backdrop')}<section class="schema-drawer" role="dialog" aria-modal="true" aria-label="Database schema"><div class="inspector-header"><h2>${icon('table')} Database schema</h2>${action(icon('close'),'schema','aria-label="Close schema"','iconbutton schema-close')}</div>${schema()}${state.result?table(state.result):''}</section></div>`:''}${state.commandOpen?commandMenu():''}`;};
// The same editor/results implementation is used by tools and projects.
editorPanel=()=>workspaceEditor(false);
execute=function(mode='run',override=null){
 if(state.busy)return;rememberWorkspace();const serial=++state.runSerial,id=state.id,variant=state.variant,page=state.page,project=state.caseId;
 const l=lessons[page==='assessment'?placementIds[state.placementIndex]:id],t=l.tasks[page==='assessment'?0:variant],graded=mode==='check'&&['practice','assessment'].includes(page),guided=page==='practice'?attempt().guided:false;
 const input=document.getElementById('query'),selection=input?[input.selectionStart,input.selectionEnd]:null,focused=document.activeElement===input;
 if(mode==='walk'&&page==='practice')guidance('walkthrough');state.busy=true;state.feedback=null;state.execution=null;state.outputTab=mode==='plan'?'plan':'results';render();
 const w=new Worker('engine.js');worker=w;const finish=()=>{clearTimeout(timer);w.terminate();if(serial!==state.runSerial)return false;state.busy=false;return true;};
 const paint=()=>{render();if(focused&&['run','check'].includes(mode)){const el=document.getElementById('query');el?.focus?.({preventScroll:true});if(selection)el?.setSelectionRange?.(...selection);}};
 const fail=message=>{if(!finish())return;if(mode==='example'){state.exampleResult=null;toast(message);}else if(mode==='walk'){state.walkError=message;}else{state.execution={ok:false,technical:message,category:classifyFailure({error:message})};state.result=null;state.feedback={ok:false,title:'Query needs attention',message,category:classifyFailure({error:message})};if(graded&&page==='practice'){update(false,guided,id,variant,state.feedback.category);if(project!==null)recordProject(false,guided,null);}}paint();};
 w.onmessage=({data})=>{if(serial!==state.runSerial||data.ready)return;if(data.error)return fail(data.error);if(!finish())return;
 if(data.comparison){state.comparison={outputs:data.comparison,equivalent:data.equivalent};paint();return;}
 const result={...data.result,total:data.total};if(mode==='example'){state.exampleResult=result;paint();return;}if(mode==='walk'){state.walkResult=result;state.walkError=null;paint();return;}
 if(mode==='plan')state.plan=result;else state.result=result;state.execution={ok:true,total:data.total};
 if(data.grade){state.expected=data.expected;const category=data.grade.ok?null:classifyFailure(data);if(page==='assessment'){learning.placement.answers[state.placementIndex]={ok:data.grade.ok,time:Date.now()};safePersist();}else{update(data.grade.ok,guided,id,variant,category);if(project!==null)recordProject(data.grade.ok,guided,result);}
 state.execution.category=category;if(data.expected)state.execution.evidence=`Returned ${result.values.length} of ${data.expected.values.length} required rows · ${result.columns.length} of ${data.expected.columns.length} required columns${result.columns.join('|').toLowerCase()===data.expected.columns.join('|').toLowerCase()?' · Column names and order passed':''}.`;state.feedback={ok:data.grade.ok,title:data.grade.ok?(page==='assessment'?'Diagnostic answer passed':guided?'Guided practice completed':'Independent solve recorded'):'Let’s refine the answer',message:data.grade.ok?(page==='assessment'?'Diagnostic answer passed. No lesson mastery was awarded.':guided?'Try a fresh dataset attempt without challenge-specific assistance to earn independent credit.':'Passed the original and changed-data checks.'):data.grade.message,category};safePersist();}
 paint();};w.onerror=()=>fail('The SQL engine could not start. Refresh and retry.');timer=setTimeout(()=>fail('Query exceeded the three-second limit. Try a smaller query.'),3000);
 w.postMessage({seed:seed+(page==='practice'&&attempt().fresh?fixtureMutation+freshDataMutation:''),query:override??state.query,answer:graded?t.answer:null,ordered:t.ordered,explain:mode==='plan',mutation:graded?(page==='practice'&&attempt().fresh?freshDataMutation:fixtureMutation):null,allowWrites:page==='lab'||page==='practice'&&l.mode==='lab',validate:graded?t.validate:null,required:graded?t.required:null,compare:mode==='compare'?planComparisons[state.planChoice].cases:null});
};
function download(name,text,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function confirmAction(title,fn){const d=document.createElement('dialog');d.innerHTML=`<h2>${esc(title)}</h2><p>This action replaces the current saved work. Export anything you want to keep first.</p><div class="actions"><button class="outline" data-cancel>Cancel</button><button class="primary" data-confirm>Confirm</button></div>`;document.body.append(d);d.querySelector('[data-cancel]').onclick=()=>d.close();d.querySelector('[data-confirm]').onclick=()=>{d.close();fn();};d.addEventListener('close',()=>d.remove());d.showModal();d.querySelector('[data-cancel]').focus();}
root.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||!b.dataset.action.startsWith('ux-'))return;const a=b.dataset.action.slice(3);
 if(state.busy&&!['route','schema','menu','closemenu','command','command-close'].includes(a))return;
 if(a==='route')return routeTo(b.dataset.route);if(a==='task-toggle'){state.taskCollapsed=!state.taskCollapsed;render();return;}if(a==='command')return openCommand();if(a==='command-close'){state.commandOpen=false;render();document.querySelector('.command-trigger,.mobilebar [data-action="ux-command"]')?.focus?.();return;}if(a==='appearance'){learning.preferences.theme=b.dataset.theme;safePersist();applyTheme();render();return;}if(a==='start')return routeTo('/lesson/0');if(a==='resume')return resume();if(a==='recommend')return followRecommendation();if(a==='stage')return setStage(b.dataset.stage);
 if(a==='schema'){state.schemaOpen=!state.schemaOpen;render();document.querySelector(state.schemaOpen?'.schema-close':'[data-action="ux-schema"]')?.focus?.();return;}
 if(a==='menu'||a==='closemenu'){state.menuOpen=a==='menu'?!state.menuOpen:false;render();document.querySelector(state.menuOpen?'.menuclose':'.menutoggle')?.focus?.();return;}
 if(a==='collapse'){learning.preferences.collapsed=!learning.preferences.collapsed;safePersist();render();return;}
 if(['run','check','plan'].includes(a))return execute(a);
 if(a==='edit'){document.getElementById('query')?.focus?.();return;}if(a==='search'){render();return;}if(a==='output'){state.outputTab=b.dataset.tab;render();return;}
 if(a==='expected'){if(!state.expected||state.page==='assessment')return;if(state.page==='practice'&&!ownSolves().includes(state.variant))guidance('expected output');state.outputTab='expected';render();return;}
 if(a==='hint'){guidance('hint');state.helpOpen=true;state.hint=attempt().hints;render();return;}
 if(a==='reveal'){guidance('solution');state.helpOpen=true;render();return;}
 if(a==='fresh')return freshAttempt();
 if(a==='variant'){rememberWorkspace();loadLesson(state.id,+b.dataset.variant,state.caseId);state.stage='practice';persistDraft();render();return;}
 if(a==='quiz')return completeQuiz(+b.dataset.choice);
 if(a==='next'||a==='previous'||a==='skip'){const ids=state.caseId!==null?caseStudyGroups[state.caseId].ids:courseOrder,i=ids.indexOf(state.id),next=ids[i+(a==='previous'?-1:1)];if(next!==undefined)openLesson(next);else routeTo(state.caseId!==null?'/projects/'+state.caseId:'/learn');return;}
 if(a==='example-run')return execute('example',lessons[state.id].example);
 if(a==='copy'||a==='copy-example'){try{await navigator.clipboard.writeText(a==='copy-example'?lessons[state.id].example:state.query);toast('SQL copied.');}catch(err){toast('Select the SQL in the editor and copy it.');}return;}
 if(a==='reset'){state.resetConfirm=!state.resetConfirm;render();return;}if(a==='reset-cancel'){state.resetConfirm=false;render();return;}if(a==='reset-confirm'){state.query=state.page==='practice'?starter(state.id):state.page==='assessment'?'-- Write SQL for this diagnostic question\n':'SELECT * FROM '+datasetCatalog[state.dataset].tables[0]+';';state.resetConfirm=false;persistDraft();render();return;}
 if(a==='clear-filters'){state.search='';state.filterLevel='all';state.filterStatus='all';state.pathGroup=-1;render();return;}
 if(a==='export')return download('sql-studio-progress.json',JSON.stringify(exportData(),null,2));
 if(a==='clear')return confirmAction('Reset learning progress?',()=>{const pref=learning.preferences;for(const key of Object.keys(learning.drafts))try{sessionStorage.removeItem?.(key)}catch(e){}learning=migrateLearning({});learning.preferences=pref;state.stats=learning.stats;state.history=learning.history;safePersist();routeTo('/');});
 if(a==='export-project'){const p=+b.dataset.project,r=projectRecord(p);const output=caseStudyGroups[p].ids.map(id=>'-- '+lessons[id].title+'\n'+[0,1].map(v=>learning.drafts[`sql-project-${p}-${id}-${v}`]||r.milestones[id]?.queries?.[v]||'-- Not yet written').join('\n\n')).join('\n\n');return download('sql-project-'+p+'.sql',output,'text/plain');}
 if(a==='export-summary'){const p=+b.dataset.project;return download('sql-project-'+p+'-summary.json',JSON.stringify({project:projectNames[p],...projectRecord(p)},null,2));}
 if(a==='placement-next'){const p=learning.placement;if(!p.answers[state.placementIndex])p.answers[state.placementIndex]={ok:false,time:Date.now()};p.index++;p.done=p.index>=placementIds.length;state.placementIndex=p.index;state.execution=null;state.feedback=null;state.result=null;state.expected=null;if(!p.done)loadPlacement();safePersist();render();return;}
 if(a==='review-answer'&&!state.reviewResult){const ok=+b.dataset.choice===quizFor(state.reviewId).correct,r=learning.reviews[state.reviewId]||{step:0,history:[]};r.step=ok?Math.min(3,(r.step||0)+1):0;r.due=Date.now()+REVIEW_DAYS[r.step]*86400000;r.history=[...(r.history||[]),{time:Date.now(),ok}].slice(-30);learning.reviews[state.reviewId]=r;state.reviewResult={ok};safePersist();render();}
});
root.addEventListener('input',e=>{if(e.target.id==='ux-search')state.search=e.target.value;});
root.addEventListener('change',async e=>{const id=e.target.id;if(e.target.classList?.contains('ux-theme')){learning.preferences.theme=e.target.value;safePersist();applyTheme();root.querySelectorAll?.('.ux-theme').forEach(el=>el.value=e.target.value);root.querySelectorAll?.('.theme-control>.icon').forEach(el=>el.innerHTML=icons[e.target.value==='system'?'monitor':e.target.value==='dark'?'moon':'sun']);}
 if(id==='ux-milestone'){routeTo('/projects/'+state.caseId+'/milestone/'+e.target.value);return;}if(id==='ux-module'){state.pathGroup=+e.target.value;render();}if(id==='ux-level'||id==='ux-status'){state[id==='ux-level'?'filterLevel':'filterStatus']=e.target.value;render();}
 if(id==='ux-import'){try{importLearning(JSON.parse(await e.target.files[0].text()));applyTheme();routeTo('/');toast('Progress imported.');}catch(err){toast('Could not import: '+err.message);}}
});
root.addEventListener('click',e=>{const b=e.target.closest('[data-action="walkstep"]');if(b&&state.page==='practice'){const step=stepsFor(state.id)[+b.dataset.step];if(step?.query.trim()===lessons[state.id].tasks[state.variant].answer.trim())guidance('walkthrough');}});
root.addEventListener('toggle',e=>{if(e.target.classList?.contains('walkthrough-disclosure')&&e.target.open){const steps=stepsFor(state.id);if(steps.some(s=>(s.sql||s.query||'').trim()===lessons[state.id].tasks[state.variant].answer.trim()))guidance('walkthrough');}},true);
root.addEventListener('keydown',e=>{if(!state.schemaOpen)return;if(e.key==='Escape'){state.schemaOpen=false;render();document.querySelector('[data-action="ux-schema"]')?.focus?.();}if(e.key==='Tab'){const els=[...document.querySelectorAll('.schema-drawer button,.schema-drawer summary,.schema-drawer select')];const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first||!e.shiftKey&&document.activeElement===last){e.preventDefault();(e.shiftKey?last:first)?.focus();}}});
if(typeof window!=='undefined'){window.addEventListener('popstate',()=>routeTo(location.hash.slice(1)||'/',false));window.matchMedia?.('(prefers-color-scheme: dark)').addEventListener?.('change',()=>{if(learning.preferences.theme==='system')applyTheme();});window.visualViewport?.addEventListener('resize',()=>document.documentElement.setAttribute('data-keyboard',Math.max(window.innerHeight,document.documentElement.clientHeight||0)-window.visualViewport.height>150&&document.activeElement?.id==='query'?'true':'false'));}
const renderUnified=render;render=function(){const old=root.querySelector?.('.editor'),oldInput=old?.querySelector?.('textarea'),keep=old?.dataset.draft===draftKey()&&oldInput?.value===state.query;renderUnified();if(keep){const replacement=root.querySelector?.('.editor');replacement?.replaceWith?.(old);}const modal=state.menuOpen||state.schemaOpen;const main=root.querySelector?.('main');if(main)main.inert=modal;const bottom=root.querySelector?.('.bottomnav');if(bottom)bottom.inert=modal;const side=root.querySelector?.('.sidebar');if(side)side.inert=state.schemaOpen;const mobile=root.querySelector?.('.mobilebar');if(mobile)mobile.inert=modal;const skip=root.querySelector?.('.skiplink');if(skip)skip.inert=modal;};
const schemaOriginal=schema;schema=function(){let html=schemaOriginal();if(['practice','assessment'].includes(state.page))html=html.replace(/<label for="dataset">Database<\/label><select id="dataset">[\s\S]*?<\/select>/,'<strong>'+esc(datasetCatalog[state.dataset].name)+'</strong>');return html;};
applyTheme();routeTo(typeof location!=='undefined'?location.hash.slice(1)||'/':'/',false);
root.addEventListener('click',e=>{if(e.target.closest?.('.skiplink')){e.preventDefault();document.getElementById('main-content')?.focus?.();}});
function activityRows(history){return [...history].reverse().map(h=>`<div class="activity-row"><span class="activity-mark">${icon(h.ok?'complete':'error')}</span><div><h3>${link(esc(lessons[h.id].title),h.project!==null&&h.project!==undefined?`/projects/${h.project}/milestone/${h.id}`:'/lesson/'+h.id,'row-title')}</h3><span class="metadata">${new Date(h.time).toLocaleString()} · ${h.guided?'Guided practice':'Independent attempt'} · ${h.ok?'Correct':'Needs revision'}</span></div>${link(icon('arrow'),'/lesson/'+h.id,'iconbutton').replace('data-route=','aria-label="Open lesson" title="Open lesson" data-route=')}</div>`).join('');}
function settingsView(){return `<header class="page-intro"><div><h1>Settings</h1><p>Make the workspace comfortable for you.</p></div></header><section class="settings-section"><h2>Appearance</h2><p class="note">System follows your device. Your choice is saved in this browser.</p><div class="appearance-options" role="group" aria-label="Appearance">${['light','dark','system'].map(t=>action(icon(t==='system'?'monitor':t==='dark'?'moon':'sun')+' '+t[0].toUpperCase()+t.slice(1),'appearance',`data-theme="${t}" aria-pressed="${learning.preferences.theme===t}"`,'outline')).join('')}</div></section><section class="settings-section"><h2>Navigation</h2><div class="setting-row"><div><h3>Desktop sidebar</h3><p class="note">Keep labels visible or use a compact icon rail.</p></div>${action(learning.preferences.collapsed?'Expand sidebar':'Collapse sidebar','collapse','','outline')}</div></section><section class="settings-section"><h2>Your learning data</h2><p class="note">${storageOK?'Progress, drafts and project deliverables are saved locally.':'Browser storage is unavailable. Export before leaving.'} No account or cloud sync is required.</p><div class="actions">${action('Export progress','export','','outline')}<label class="importbutton">Import progress<input type="file" id="ux-import" accept="application/json" hidden></label>${link('Learning progress','/progress')}</div></section><section class="settings-section"><h2>Keyboard shortcuts</h2><dl class="shortcut-list"><div><dt>Search and quick navigation</dt><dd><kbd>⌘ / Ctrl</kbd> + <kbd>K</kbd></dd></div><div><dt>Run query</dt><dd><kbd>⌘ / Ctrl</kbd> + <kbd>Enter</kbd></dd></div><div><dt>Check answer in Practice</dt><dd><kbd>⇧</kbd> + <kbd>⌘ / Ctrl</kbd> + <kbd>Enter</kbd></dd></div><div><dt>Indent SQL</dt><dd><kbd>Tab</kbd></dd></div></dl></section>`;}
function commandItems(){const q=(state.commandQuery||'').toLowerCase().trim(),destinations=[...mainNav,...toolNav,['/settings','settings','Settings']].filter(([path,i,label])=>label.toLowerCase().includes(q)).map(([route,i,label])=>({route,icon:i,label,detail:'Workspace'}));const modules=groups.map((label,i)=>({route:'/learn/'+i,icon:'book',label,detail:'Module '+(i+1)})).filter(x=>x.label.toLowerCase().includes(q));const matches=q?courseOrder.map(id=>lessons[id]).filter(l=>`${l.title} ${l.concept} ${groups[l.group]}`.toLowerCase().includes(q)).slice(0,12).map(l=>({route:'/lesson/'+l.id,icon:'code',label:l.title,detail:groups[l.group]})):[];return [...destinations,...modules,...matches].slice(0,18);}
function commandOptions(){const items=commandItems();state.commandSelection=Math.max(0,Math.min(state.commandSelection||0,items.length-1));return items.length?items.map((x,i)=>`<button id="command-option-${i}" role="option" tabindex="-1" aria-selected="${state.commandSelection===i}" class="command-option ${state.commandSelection===i?'selected':''}" data-action="ux-route" data-route="${x.route}">${icon(x.icon)}<span>${esc(x.label)}<small>${esc(x.detail)}</small></span>${icon('arrow')}</button>`).join(''):'<p class="empty">No matching destination or lesson. Try a SQL concept such as JOIN.</p>';}
function commandMenu(){return `<section class="command-popover" aria-label="Search and quick navigation"><div class="command-input">${icon('search')}<input id="command-search" aria-label="Search destinations, modules and lessons" role="combobox" aria-controls="command-results" aria-expanded="true" aria-autocomplete="list" autocomplete="off" placeholder="Search a lesson, concept or workspace…" value="${esc(state.commandQuery||'')}">${action(icon('close'),'command-close','aria-label="Close search"','iconbutton')}</div><div id="command-results" role="listbox" aria-label="Matching destinations">${commandOptions()}</div><footer><span>↑ ↓ to browse</span><span>Enter to open · Esc to close</span></footer></section>`;}
function openCommand(){state.menuOpen=false;state.schemaOpen=false;state.commandOpen=!state.commandOpen;state.commandQuery='';state.commandSelection=0;render();if(state.commandOpen)document.getElementById('command-search')?.focus?.();}
root.addEventListener('input',e=>{if(e.target.id==='command-search'){state.commandQuery=e.target.value;state.commandSelection=0;const list=document.getElementById('command-results');if(list)list.innerHTML=commandOptions();}});
if(typeof window!=='undefined')window.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openCommand();return;}if(!state.commandOpen)return;if(e.key==='Escape'){e.preventDefault();state.commandOpen=false;render();document.querySelector('.command-trigger,.mobilebar [data-action="ux-command"]')?.focus?.();return;}const items=commandItems();if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();state.commandSelection=(state.commandSelection+(e.key==='ArrowDown'?1:-1)+items.length)%Math.max(1,items.length);const list=document.getElementById('command-results');if(list)list.innerHTML=commandOptions();document.getElementById('command-search')?.setAttribute?.('aria-activedescendant','command-option-'+state.commandSelection);document.getElementById('command-option-'+state.commandSelection)?.scrollIntoView?.({block:'nearest'});}if(e.key==='Enter'&&items[state.commandSelection]){e.preventDefault();routeTo(items[state.commandSelection].route);}});
root.addEventListener('click',e=>{if(!state.commandOpen)return;const b=e.target.closest?.('[data-action]');if(b?.dataset.action==='ux-command'||e.target.closest?.('.command-popover'))return;state.commandOpen=false;root.querySelector?.('.command-popover')?.remove?.();});
root.addEventListener('keydown',e=>{if(!state.menuOpen&&!state.schemaOpen)return;const schemaVisible=state.schemaOpen;if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation?.();state.menuOpen=false;state.schemaOpen=false;render();document.querySelector(schemaVisible?'[data-action="ux-schema"]':'.menutoggle')?.focus?.();return;}if(e.key!=='Tab')return;const area=schemaVisible?'.schema-drawer':'#site-sidebar',els=[...document.querySelectorAll(area+' button,'+area+' select,'+area+' summary,'+area+' input,'+area+' a,'+area+' [tabindex="0"]')].filter(el=>!el.disabled&&(el.offsetParent!==null||el.getClientRects?.().length));const first=els[0],last=els.at(-1);if(first&&last&&(e.shiftKey&&document.activeElement===first||!e.shiftKey&&document.activeElement===last)){e.preventDefault();e.stopImmediatePropagation?.();(e.shiftKey?last:first).focus();}},true);
root.addEventListener('change',e=>{if(e.target.id!=='dataset'||!['playground','lab'].includes(state.page))return;cancelWork();state.runSerial++;state.result=null;state.plan=null;state.feedback=null;state.execution=null;state.query=learning.drafts[draftKey()]??state.query;render();});
